Compose_Task_Acknowledgement_Link.inputs:
@concat(
  'https://taskack.page.gd/index.html',
  '?item=',
  string(coalesce(outputs('Get_item_Task_Email')?['body/ID'], 0)),
  '&name=',
  uriComponent(
    first(
      split(
        trim(replace(replace(string(coalesce(outputs('Get_item_Task_Email')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' ')),
        '@'
      )
    )
