    trim(replace(replace(string(coalesce(outputs('Get_item_Task_Email')?['body/AssignedTo'], '')), '\n', ' '), '\r', ' '))
  ),
  '&title=',
  uriComponent(
    trim(replace(replace(string(coalesce(outputs('Get_item_Task_Email')?['body/Title'], '')), '\n', ' '), '\r', ' '))
  ),
  '&ref=',
  uriComponent(
    outputs('Compose_Task_Ref')
  )
)

