parameters.item/StartDate:
@if(
  or(
    empty(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['StartDate']),
    not(contains(
      string(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['StartDate']),
      'T'
    )),
    less(
      length(string(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['StartDate'])),
      19
    )
  ),
  formatDateTime(
    convertTimeZone(
      convertTimeZone(
        utcNow(),
        'UTC',
        'W. Central Africa Standard Time'
      ),
      'W. Central Africa Standard Time',
      'UTC'
    ),
    'yyyy-MM-ddTHH:mm:ssZ'
  ),
  formatDateTime(if(empty(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['StartDate']),'1900-01-01T00:00:00Z',string(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['StartDate'])),'yyyy-MM-ddTHH:mm:ssZ')
)

parameters.item/Acknowledgement_x0020_Due_x0020_:
@if(
  empty(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['AckDue']),
  convertTimeZone(
    addDays(
      convertTimeZone(
        utcNow(),
        'UTC',
        'W. Central Africa Standard Time'
      ),
      if(
        equals(
          dayOfWeek(
            convertTimeZone(
              utcNow(),
              'UTC',
              'W. Central Africa Standard Time'
            )
          ),
          5
        ),
        3,
        if(
          equals(
            dayOfWeek(
              convertTimeZone(
                utcNow(),
                'UTC',
                'W. Central Africa Standard Time'
              )
            ),
            6
          ),
          2,
          1
        )
      )
    ),
    'W. Central Africa Standard Time',
    'UTC'
  ),
  formatDateTime(if(empty(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['AckDue']),'1900-01-01T00:00:00Z',string(outputs('Compose_Email_Task_Input')?['NewActivityTask']?['AckDue'])),'yyyy-MM-ddTHH:mm:ssZ')
)

